    console.log('Valid cases:');
    console.log(isValidBrackets('()')); // true
    console.log(isValidBrackets('[]')); // true
    console.log(isValidBrackets('{}')); // true
    console.log(isValidBrackets('()[]{}')); // true
    console.log(isValidBrackets('[()]{}')); // true
    console.log(isValidBrackets('{[]}')); // true
    console.log(isValidBrackets('a(b)c[d]e{f}')); // true (non-brackets ignored)
    console.log(isValidBrackets('')); // true (empty string)
    console.log(isValidBrackets('abc')); // true (only non-brackets)

    // Invalid cases
    console.log('\nInvalid cases:');
    console.log(isValidBrackets('(]')); // false
    console.log(isValidBrackets('([)]')); // false
    console.log(isValidBrackets('{[]}')); // true
    console.log(isValidBrackets('{[}')); // false
    console.log(isValidBrackets('(()')); // false (unclosed)
    console.log(isValidBrackets('())')); // false (extra closing)
    console.log(isValidBrackets('((())')); // false (unclosed)
    console.log(isValidBrackets('((())))')); // false (extra closing)

    // Deep nesting
    console.log('\nDeep nesting:');
    console.log(isValidBrackets('[' + '('.repeat(1000) + ')'.repeat(1000) + ']')); // true
    console.log(isValidBrackets('[' + '('.repeat(1000) + ')'.repeat(999) + ']')); // false (unclosed)
    console.log(isValidBrackets('[' + '('.repeat(1000) + ')'.repeat(1001) + ']')); // false (extra closing)

    // Error cases
    console.log('\nError cases:');
    try {
        console.log(isValidBrackets(null)); // should throw
    } catch (e) {
        console.log('Caught error for null:', e.message);
    }

    try {
        console.log(isValidBrackets(123)); // should throw
    } catch (e) {
        console.log('Caught error for number:', e.message);
    }

    try {
        console.log(isValidBrackets({})); // should throw
    } catch (e) {
        console.log('Caught error for object:', e.message);
    }
}

testIsValidBrackets();
```

### Explanation:

1. **Non-bracket characters**: The function explicitly ignores any characters that aren't `()[]{}`. They're simply skipped during processing.

2. **Edge cases handled**:
   - Empty string: Returns true (no unmatched brackets)
   - String with only ordinary characters: Returns true (no unmatched brackets)
   - Deeply nested brackets: Handled efficiently with the stack
   - Extra closing brackets: Detected when stack is empty but encounter a closing bracket
   - Unclosed opening brackets: Detected when stack isn't empty after processing all characters
   - Invalid input types: Throws TypeError for non-string inputs

3. **Complexity Analysis**:
   - **Time Complexity**: O(n) - We process each character exactly once.
   - **Space Complexity**: O(n) - In the worst case (all opening brackets), the stack will grow to the size of the input string.

4. **Algorithm**:
   - Use a stack to track opening brackets
   - When encountering an opening bracket, push it onto the stack
   - When encountering a closing bracket:
     - If stack is empty, return false (no matching opening bracket)
     - Pop from stack and check if it matches the expected opening bracket
   - After processing all characters, return true if stack is empty, false otherwise

The implementation follows strict LIFO (Last In, First Out) logic for bracket matching, ensuring proper nesting and pairing.

I'll implement both iterative and recursive variants of binary search that return the first occurrence of the target in a sorted array.

```js
/**
 * Performs binary search to find the first occurrence of target in a sorted array.
 * Time complexity: O(log n), Space complexity: O(1)
 * @param {Array} sorted - The sorted array to search in (must be sorted in ascending order)
 * @param {*} target - The value to search for
 * @returns {number} The index of the first occurrence of target, or -1 if not found
 */
function binarySearch(sorted, target) {
    if (!Array.isArray(sorted)) {
        return -1;
    }

    let left = 0;
    let right = sorted.length - 1;
    let result = -1;

    while (left <= right) {
        const mid = left + Math.floor((right - left) / 2);

        if (sorted[mid] === target) {
            result = mid;
            right = mid - 1; // Continue searching left for earlier occurrences
        } else if (sorted[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return result;
}

/**
 * Recursive binary search to find the first occurrence of target in a sorted array.
 * Time complexity: O(log n), Space complexity: O(log n) due to recursion stack
 * @param {Array} sorted - The sorted array to search in (must be sorted in ascending order)
 * @param {*} target - The value to search for
 * @param {number} [left=0] - The left boundary of the search range (internal use)
 * @param {number} [right] - The right boundary of the search range (internal use)
 * @returns {number} The index of the first occurrence of target, or -1 if not found
 */
function binarySearchRecursive(sorted, target, left = 0, right = sorted ? sorted.length - 1 : -1) {
    // Validate input (safe for null/undefined)
    if (!Array.isArray(sorted)) {
        return -1;
    }

    // Base case: search range is invalid
    if (left > right) {
        return -1;
    }

    const mid = left + Math.floor((right - left) / 2);

    if (sorted[mid] === target) {
        // Found target, but continue searching left for earlier occurrences
        const leftResult = binarySearchRecursive(sorted, target, left, mid - 1);
        return leftResult !== -1 ? leftResult : mid;
    } else if (sorted[mid] < target) {
        return binarySearchRecursive(sorted, target, mid + 1, right);
    } else {
        return binarySearchRecursive(sorted, target, left, mid - 1);
    }
}
```

### Explanation:

**Requirements Met:**
1. **Time Complexity:** Both implementations are O(log n) as they halve the search space each iteration.
2. **Space Complexity:**
   - Iterative: O(1) - uses constant space for variables
   - Recursive: O(log n) - uses stack space proportional to recursion depth
3. **First Occurrence:** Both functions find the first occurrence by continuing the search to the left when a match is found.
4. **Input Safety:** The recursive variant validates the input before processing.
5. **Midpoint Calculation:** Uses the safe formula `left + Math.floor((right - left) / 2)` to prevent overflow.
6. **Input Preservation:** Neither function mutates or sorts the input array.

**Edge Cases Handled:**
- Empty array: returns -1
- Target not present: returns -1
- Array with all identical elements: returns 0 (first occurrence)
- Null/undefined input: returns -1 (recursive variant)
- Single-element array: returns 0 if match, -1 if not

**Contract:**
- The input array must be sorted in ascending order. If not, the behavior is undefined.
- When the target is absent, the function returns -1.
- The input array is never mutated or sorted by the function.
- For duplicate values, the function returns the index of the first occurrence.

**Example Usage:**
```js
const arr = [1, 2, 2, 2, 3, 4, 5];
console.log(binarySearch(arr, 2)); // 1 (first occurrence)
console.log(binarySearch(arr, 6)); // -1 (not found)
console.log(binarySearchRecursive(arr, 2)); // 1 (first occurrence)
console.log(binarySearchRecursive(null, 2)); // -1 (null input)
```

